  String shiftFor(DateTime d){if(shiftMode!='dual')return shiftOne;final diff=d.difference(rotationStart).inDays,week=(diff/7).floor();return (((week%2)+2)%2)==0?shiftOne:shiftTwo;}
  Map<String,int> analyze(DateTime d){if(d.weekday==DateTime.friday)return{'worked':0,'late':0,'early':0,'overtime':0,'status':0};final i=ins[key(d)],o=outs[key(d)];if(i==null&&o==null)return{'worked':0,'late':0,'early':0,'overtime':0,'status':1};if(i==null||o==null)return{'worked':0,'late':0,'early':0,'overtime':0,'status':2};final m=worked(i,o),s=shiftFor(d),si=s=='morning'?360:840,so=s=='morning'?840:1320;var ai=tmin(i),ao=tmin(o);if(ao<=ai)ao+=1440;final rawLate=(ai-si).clamp(0,9999).toInt(),rawEarly=(so-ao).clamp(0,9999).toInt(),overtime=(ao-so).clamp(0,9999).toInt();return{'worked':m,'late':rawLate>lateGrace?rawLate:0,'early':rawEarly>earlyGrace?rawEarly:0,'overtime':overtime,'status':3};}
  int get total=>dates.fold(0,(s,d)=>s+analyze(d)['worked']!); int get totalLate=>dates.fold(0,(s,d)=>s+analyze(d)['late']!); int get totalEarly=>dates.fold(0,(s,d)=>s+analyze(d)['early']!); int get totalOvertime=>dates.fold(0,(s,d)=>s+analyze(d)['overtime']!);
