  Future<void> load() async {if(employee.text.trim().isEmpty)return;final db=Supabase.instance.client;final g=await db.from('app_settings').select().eq('id',1).maybeSingle();final p=await db.from('employee_policies').select().eq('employee_name',employee.text.trim()).maybeSingle();final a=await db.from('attendances').select().eq('employee_name',employee.text.trim()).gte('work_date',key(start)).lte('work_date',key(end));setState((){lateGrace=(g?['default_late_grace']??15) as int;earlyGrace=(g?['default_early_grace']??5) as int;shiftMode=(p?['shift_mode']??'single') as String;shiftOne=(p?['shift_one']??'morning') as String;shiftTwo=(p?['shift_two']??'evening') as String;rotationStart=DateTime.tryParse(p?['rotation_start']?.toString()??'')??start;ins.clear();outs.clear();for(final r in a){final d=DateTime.parse(r['work_date']);if(r['check_in']!=null){final x=r['check_in'].toString().split(':');ins[key(d)]=TimeOfDay(hour:int.parse(x[0]),minute:int.parse(x[1]));}if(r['check_out']!=null){final x=r['check_out'].toString().split(':');outs[key(d)]=TimeOfDay(hour:int.parse(x[0]),minute:int.parse(x[1]));}}message='تم التحميل';});}
  Future<void> save() async {if(employee.text.trim().isEmpty){setState(()=>message='اكتب اسم الموظف');return;}final db=Supabase.instance.client;await db.from('app_settings').upsert({'id':1,'default_late_grace':lateGrace,'default_early_grace':earlyGrace});await db.from('employee_policies').upsert({'employee_name':employee.text.trim(),'shift_mode':shiftMode,'shift_one':shiftOne,'shift_two':shiftTwo,'rotation_start':key(rotationStart)},onConflict:'employee_name');final rows=dates.where((d)=>d.weekday!=DateTime.friday).where((d)=>ins[key(d)]!=null||outs[key(d)]!=null).map((d)=>{'employee_name':employee.text.trim(),'work_date':key(d),'check_in':ins[key(d)]==null?null:fmt(ins[key(d)]),'check_out':outs[key(d)]==null?null:fmt(outs[key(d)])}).toList();if(rows.isNotEmpty)await db.from('attendances').upsert(rows,onConflict:'employee_name,work_date');setState(()=>message='تم حفظ الدوام والورديات');}
  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('نظام حساب دوام الموظفين')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:employee,decoration:const InputDecoration(labelText:'اسم الموظف',border:OutlineInputBorder())),const SizedBox(height:12),Wrap(spacing:12,runSpacing:12,children:[DropdownButton<String>(value:shiftMode,items:const [DropdownMenuItem(value:'single',child:Text('وردية واحدة')),DropdownMenuItem(value:'dual',child:Text('ورديتان كل 7 أيام'))],onChanged:(v)=>setState(()=>shiftMode=v!)),DropdownButton<String>(value:shiftOne,items:const [DropdownMenuItem(value:'morning',child:Text('الوردية 1: صباحي')),DropdownMenuItem(value:'evening',child:Text('الوردية 1: مسائي'))],onChanged:(v)=>setState(()=>shiftOne=v!)),if(shiftMode=='dual') DropdownButton<String>(value:shiftTwo,items:const [DropdownMenuItem(value:'morning',child:Text('الوردية 2: صباحي')),DropdownMenuItem(value:'evening',child:Text('الوردية 2: مسائي'))],onChanged:(v)=>setState(()=>shiftTwo=v!)),if(shiftMode=='dual') OutlinedButton(onPressed:() async {final d=await showDatePicker(context:context,firstDate:DateTime(2020),lastDate:DateTime(2100),initialDate:rotationStart);if(d!=null)setState(()=>rotationStart=d);},child:Text('بداية الدورة: ${key(rotationStart)}')),SizedBox(width:170,child:TextFormField(initialValue:'$lateGrace',decoration:const InputDecoration(labelText:'سماح التأخير للجميع'),keyboardType:TextInputType.number,onChanged:(v)=>setState(()=>lateGrace=int.tryParse(v)??0))),SizedBox(width:190,child:TextFormField(initialValue:'$earlyGrace',decoration:const InputDecoration(labelText:'سماح الانصراف المبكر للجميع'),keyboardType:TextInputType.number,onChanged:(v)=>setState(()=>earlyGrace=int.tryParse(v)??0))),FilledButton(onPressed:load,child:const Text('تحميل')),FilledButton(onPressed:save,child:const Text('حفظ'))]),const SizedBox(height:12),Wrap(spacing:12,children:[Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('الحضور: ${total~/60}س ${total%60}د'))),Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('الأيام: ${(total/480).toStringAsFixed(6)}'))),Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('الإضافي: ${totalOvertime~/60}س ${totalOvertime%60}د'))),Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('التأخير: $totalLate د'))),Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('المبكر: $totalEarly د'))),Card(child:Padding(padding:const EdgeInsets.all(12),child:Text('غياب: $absent | معلق: $pending'))),Text(message)]),const Divider(),...dates.map((d){final friday=d.weekday==DateTime.friday,a=analyze(d),s=shiftFor(d),status=a['status']==1?'غياب':a['status']==2?'معلق':'حضور';return Card(child:ListTile(title:Text('${key(d)}${friday?' — الجمعة':''}'),subtitle:friday?const Text('إجازة الجمعة'):Text('${s=='morning'?'06:00–14:00':'14:00–22:00'} | ${a['worked']!~/60}س ${a['worked']!%60}د | إضافي ${a['overtime']!~/60}س ${a['overtime']!%60}د | تأخير ${a['late']}د | مبكر ${a['early']}د | $status'),trailing:friday?null:Wrap(spacing:8,children:[OutlinedButton(onPressed:()=>pick(d,true),child:Text(ins[key(d)]?.format(context)??'الحضور')),OutlinedButton(onPressed:()=>pick(d,false),child:Text(outs[key(d)]?.format(context)??'الانصراف'))])));})]));
}
